\cite[Definition 3.6]{ABC25}
	\label{def:Cseparatedword-and-compatible}
    Let $(E,C)$ be a separated graph. 
	A {\it $C$-separated path} is a reduced path $w=y_1\cdots y_n\in \mathfrak{F_{gr}} (E)$, with $y_i\in \hat{E}^1$, that does not contain any subpath of the form $x^{-1}y$ with $x,y\in X$ for $X\in C$. For $v\in E^0$, we denote by $\mathbb F_{C} (v)$ the set of all $C$-separated paths $\gamma$ such that $s(\gamma ) =v$. The set $\mathbb F_{C} := \bigsqcup_{v\in E^0} \mathbb F_{C} (v)$ is the set of all $C$-separated paths.

\cite{ABC25}
	\label{def:graphsemigroup}
    Let $(E,C)$ be a separated graph. The \emph{inverse semigroup} of $(E,C)$ is the universal inverse semigroup $\mathcal{S} (E,C)$ 
    generated by $E^0\cup \hat{E}^1=E^0\cup E^1\cup E^{-1}$ subject to the following relations:
	\begin{enumerate}
		\item $vw = \delta_{v,w}v$ for all $v,w\in E^0$;
		\item $s(x)x = x$ for all $x\in \hat{E}^1$;
		\item $xr(x) = x$ for all $x\in \hat{E}^1$;
		\item $e^{-1}f = \delta_{e,f} r(e)$ for all $e,f\in X$ with $X\in C$.  
	\end{enumerate}

\cite{AG12}
\label{def:Cohn-and-Leavitt-algs}
Let $K$ be a commutative ring with an involution $*$ and let $(E,C)$ be a separated graph. The Cohn path algebra $\mathcal C_K(E,C)$ is the universal $*$-algebra over $K$ generated by 
self-adjoint elements $v\in E^0$ and elements $e\in E^1$ satisfying the following relations:
\begin{enumerate}
    \item[(V)] $vw=\delta_{v,w}v$ for all $v,w\in E^0$;
    \item[(E1)] $s(e)e= e= er(e)$ for all $e\in E^1$;
    \item[(E2)] $e^ *s(e)=e^* = r(e)e^*$ for all $e\in E^1$;
    \item[(SCK1)] $e^*f=\delta_{e,f}r(e)$ for all $e,f\in X$ with $X\in C$.
\end{enumerate}
The Leavitt path algebra $\mathcal L_K(E,C)$ is the universal $*$-algebra over $K$ generated by the same generators and relations above together with the Cuntz–Krieger relation:
\begin{enumerate}
    \item[(SCK2)] $\sum_{e\in X}ee^*=v$ for every finite subset $X\in C_v$ with $v\in E^0$.
\end{enumerate}

\cite[Proposition 6.5 and Corollary 6.10]{ABC25}
    \label{thm:structure-of-tame-Cohn}
Let $(E,C)$ be a separated graph. Then we have $*$-isomorphisms
$$\mathcal C_K^\mathrm{ab} (E,C) \cong K[\mathcal{S} (E,C)] \cong A_K(\mathcal{G} (E,C)) \cong C_K(\widehat{\mathcal E})\rtimes \mathbb F,$$
where $\widehat{\mathcal E}$ is the spectrum of $\mathcal E=\mathcal E (\mathcal{S}(E,C))$ and $\mathbb F = \mathbb F(E^1)$ is the free group on $E^1$.

\cite[Theorem 6.20]{ABC25}
    \label{thm:structure-of-Leavitt}
Let $(E,C)$ be a separated graph. Then we have $*$-isomorphisms
$$\mathcal L_K^\mathrm{ab} (E,C) \cong A_K ( \mathcal{G}_\mathrm{tight} (E,C)) \cong C_K (\widehat{\mathcal E}_\mathrm{tight} ) \rtimes \mathbb F,$$
where $\widehat{\mathcal E}_\mathrm{tight} $ is the tight spectrum of $\mathcal E=\mathcal E (\mathcal{S}(E,C))$ and $\mathbb F = \mathbb F(E^1)$ is the free group on $E^1$.

\label{def:Leavitt-inverse-semigroup}
Let $(E,C)$ be a separated graph. The {\it Leavitt inverse semigroup} of $(E,C)$ is the universal inverse semigroup $\mathcal{LI} (E,C)$  
generated by $E^0\cup \hat{E}^1=E^0\cup E^1\cup E^{-1}$ subject to the following relations:
\begin{enumerate}
	\item $vw = \delta_{v,w}v$ for all $v,w\in E^0$;
	\item $s(x)x = x$ for all $x\in \hat{E}^1$;
	\item $xr(x) = x$ for all $x\in \hat{E}^1$;
	\item $e^{-1}f = \delta_{e,f} r(e)$ for all $e,f\in X$ with $X\in C$.
	\item $ee^{-1} = s(e)$ for all $e\in E^1$ such that $\{e\} \in C$.   
\end{enumerate}
In other words, $\mathcal{LI} (E,C)$ is the quotient of the inverse semigroup $\mathcal{S} (E,C)$ of $(E,C)$ (as in Definition~\ref{def:graphsemigroup}) by the congruence generated by the relations (5).

\cite[Definition 4.1(a)]{ABC25}
 	\label{def:Mun-EC-tree} Let $E$ be a directed graph.
	A {\it Munn $E$-tree} is a pair $(T,g)$, where $T$ is a finite connected subgraph (hence a subtree) of $\Gamma_E$ containing the unit $v$ of the connected component $K_v$ corresponding to $T$, and $g$ is a vertex of $T$.

\cite[Corollary 4.3]{ABC25}
	\label{cor:FSIE-strongly-unitary}
	Let $E$ be a directed graph. Then $\mathfrak{F_{is}}(E)$ is strongly $E^*$-unitary and thus it is a restricted semidirect product 
	$$\mathfrak{F_{is}}(E) =\mathcal E (\mathfrak{F_{is}}(E)) \rtimes_\theta ^r \mathbb F,$$
	where $\mathbb F = \mathbb F (E^1)$ is the free group on $E^1$.

\label{def:canonicaldec-respect-toU}
	Let $E$ be a directed graph and let $U$ be a subset of $E^1$. For each $g\in \mathfrak{F_{gr}} (E)$, we can uniquely write $g=g_U w$, where $g_U$ is either a vertex or a prefix of $g$ such that $g_U$ does not end in $E^{-1}$ and does not end in an edge belonging to $U$, and $w$ is a product of elements of the form $f^{-1}$ for $f\in E^1$ and elements of the form $e$ for $e\in U$. 

	We say that $g=g_U w$ is the {\it canonical decomposition} of $g$ with respect to $U$. For $U=\emptyset$, we obtain the  decomposition $g= g_0w$ from \cite[Notation 3.15]{ABC25}. When $(E,C)$ is a separated graph and $U$ is the set of elements $e\in E^1$ such that $\{ e\}\in C$, this agrees with the decomposition $g=g_L w$ from Definition \ref{def:decomposition-gLw}.

\label{lem:uniqueTU}
	Let $U$ be a subset of $E^1$, and set $\mathcal M_U= \mathcal M/{\sim_U}$.
	For each $E$-tree $T$, the $\sim_U$-equivalence class $[T]_U$ of $T$ in $\mathcal M$ contains a maximum element $T_U$ with respect to the natural order in the inverse semigroup $\mathcal M$. This maximum element is the unique element $T_U$ of $[T]_U$ such that each maximal element of $T_U$ does not end in $E^{-1}$ and does not end in $e$, for $e\in U$.

\label{lem:cosequenceofuniqueTU}
With the above notation, we have, for Munn $E$-trees $(T,g)$ and $(S,h)$,
\begin{enumerate}
	\item $(T,g)\sim_U (S,h)$ if and only if $S_U= T_U$ and $g=h$.
	\item The $\sim_U$-equivalence class $[T,g]_U$ has a largest element, which is $(T_U\cup g^\downarrow , g)$.
\end{enumerate}

\label{def:Leavitt-Munn-tree}
	Let $(E,C)$ be a separated graph. 
		\begin{enumerate}
		\item[(a)] For $v\in E^0$, we denote by $\mathcal X _L (v)$ the set of all elements $T$ in $\mathcal X(v)$ such that each maximal element of $T$ does not end in $E^{-1}$ and does not end in an edge $e\in E^1$ such that $\{e\}\in C$. Observe that $\mathcal X_L(v)\subseteq \mathcal X_0(v)\subseteq \mathcal X(v)$. We set $\mathcal X _L = \bigsqcup_{v\in E^0} \mathcal X_L (v)$. We refer to the elements of $\mathcal X_L$ as {\it Leavitt $(E,C)$-trees}. 
		\item[(b)]  A {\it Leavitt-Munn $(E,C)$-tree} is a pair $(T,g)$, where $T\in \mathcal X_L$, and $g= g_L w\in \mathbb F_{C} $ satisfies that $g_L\in T$. 	
			\end{enumerate}

\label{exam:free-group-and-Dgprime}
	Let $(E,C)$ be the Cuntz separated graph, consisting of a single vertex, and where all elements of $C$ are singletons (see \cite[Example 3.4]{ABC23}). Then for each $g\in \mathbb F\setminus \{1\}$, $D_g^L$ is trivial. More generally, if $(E,C)$ is a separated graph with the free separation, that is, all elements of $C$ are singletons, then 
	the only idempotents of $\mathcal{LI} (E,C)$ are the vertices of $E$, and $D_g^L = \{\{v\}\}$ whenever $g\in \mathbb F_{C} (v)\setminus \{v\}$.

\label{lem:algebra-mathcalC-abstractly-described}
	Let $\mathcal C$ be the (commutative) subalgebra of $\mathcal C_K^\mathrm{ab}(E,C)$ generated by the idempotents of $\mathcal{S}(E,C)$. Then 
	$$\mathcal C \cong \operatorname{\mathrm{Pol}}_K[\mathbb F_{C}]/N,$$
	where $\operatorname{\mathrm{Pol}}_K[\mathbb F_{C}]$ denotes the commutative polynomial algebra on the set $\mathbb F_{C}$, and $N$ is the ideal of $\operatorname{\mathrm{Pol}}_K[\mathbb F_{C}]$ generated by the following elements
	\begin{enumerate}
		\item $\lambda \cdot \mu $ if $s(\lambda)\ne s(\mu)$. 
		\item $\lambda \cdot \mu - \lambda $ for $\mu \le_p \lambda$,
		\item $\lambda \cdot \mu $ if $\lambda$ and $\mu $ are $C$-incompatible.
		\item $\lambda e^{-1} - \lambda$ where $\lambda e^{-1}\in \mathbb F_{C}$ and $e\in E^1$.  
	\end{enumerate}

\label{thm:basis-forLabneutralcomp}
	Let $(E,C)$ be a separated graph and let $\mathfrak E\colon C^{\mathrm{fin}} \to E^1$ be a choice function. Then a $K$-basis for the neutral component $\mathcal L_1 = \mathcal C_1/\mathcal Q_1$ of $\mathcal L_K^\mathrm{ab}(E,C)$ is given by the following set: 
	$$\overline{\mathcal B}_1 (E,C) = \{ \mathbf{e} (T) : T \text{ is $\mathfrak E$-reduced } \}.$$

\label{def:relatively-reduced}
	Let $(E,C)$ be a separated graph, let $\mathfrak E\colon C^{\mathrm{fin}} \to E^1$ be a choice function, and let $g\in \mathbb F_{C}$. 
	We say that $T\in D_g^L$ is $\mathfrak E$-reduced relatively to $g_L$ if each element in $\mathrm{max} (T)\setminus \{ g_L\}$ is $\mathfrak E$-reduced. That is, if either $g_L$ is $\mathfrak E$-reduced or $g_L$ is not maximal in $T$, then $T$ is $\mathfrak E$-reduced relatively to $g_L$ if and only if $T$ is $\mathfrak E$-reduced, and if $g_L$ is not $\mathfrak E$-reduced and $g_L$ is maximal in $T$, then $T$ is $\mathfrak E$-reduced relatively to $g_L$ if and only if all maximal elements of $T$ except $g_L$ are $\mathfrak E$-reduced.

\label{thm:full-basis-forLab}
	A basis of $\mathcal L_K^\mathrm{ab}(E,C)$ is given by the elements of the form 
	$$\overline{\mathcal B} (E,C) :=\{ \mathbf{e} (T)\rtimes g : T \in D_g^L \text{ and } T \text{ is $\mathfrak E$-reduced relatively to $g_L$} \}.$$

cf. \cite[Definition 2.5]{AG12}
	\label{def:Cohn-Leavitt}
	Let $(E,C)$ be a separated graph, and let $S$ be a subset of $C^{\mathrm{fin}}$. Then let $CL_K(E,C,S)$ be the $*$-algebra with generators $E^0\cup E^1$ subject to relations (V), (E1), (E2) and (SCK1) of Definition \ref{def:Cohn-and-Leavitt-algs}, together with relation (SCK2) only for the sets $X\in S$.
 The $*$-algebra $CL_K(E,C,S)$ is called the {\it Cohn-Leavitt path algebra} of $(E,C,S)$. 	

	We denote by $CL_K^\mathrm{ab} (E,C,S)$ the tame $*$-algebra associated to the canonical set of generators $E^0\cup E^1$ of $CL_K(E,C,S)$. This will be called the  {\it tame Cohn-Leavitt path algebra} of the triple $(E,C,S)$.  Observe that $CL_K^\mathrm{ab} (E,C,S) = \mathcal C_K^\mathrm{ab} (E,C)/{\mathcal Q_S}$, where $\mathcal Q_S$ is the ideal of $\mathcal C_K^\mathrm{ab} (E,C)$ generated by the projections $q_X$, for $X\in S$.

\cite[Notation 5.10(1),(2)]{ABC25}
	\label{notati:opencompactbasis}
	\begin{enumerate}
		\item For $v\in E^0$, write
		$$\mathcal N (v) = \{ x_1^{-1}x_2^{-1}\cdots x_n^{-1}y \in \mathbb F_{C} (v) : n\ge 0, x_1,\dots , x_n,y\in E^1\}.$$
	\item 	For each $T\in \mathcal X_0$, write  
$$\mathcal N (T) : = \{gg' \in \mathbb F_{C} : g\in T,\,  g' \in \mathcal N (r(g)),\,  g[g']_1\notin T, \, \text{ and }  T\cup \{gg'\}^{\downarrow}\in \mathcal X_0 \}.$$
\end{enumerate}

\label{lem:key-for-keyforbasis-of-L}
	Let $(E,C)$ be a separated graph, let $I,J\in \mathcal X _0$ and let $F\in \mathcal N (I)$, $G\in \mathcal N (J)$. Then we have
	$$\mathbf{e}(I\setminus F) \mathbf{e}(J\setminus G)= \begin{cases}
		\mathbf{e}((I\cup J)\setminus (F\cup G)) & \text{ if } I\cup J \text{ is $C$-compatible  and }\\ & \quad F\cap J = G\cap I = \emptyset \\
		\qquad \quad  0 & \text{ otherwise }
	\end{cases}
	$$

This follows from the identity
	$$\mathcal Z(I\setminus F) \cap \mathcal Z(J\setminus G)= \begin{cases}
		\mathcal Z ((I\cup J)\setminus (F\cup G)) & \text{ if } I\cup J \text{ is $C$-compatible  and }\\ 
		&\quad F\cap J = G\cap I = \emptyset \\
		\qquad \quad  \emptyset & \text{ otherwise }
	\end{cases}
	$$
	which has been shown in \cite[Lemma 5.11]{ABC25}.

\label{def:filters-ultra-tight}
	\begin{enumerate}
		\item For $v\in E^0$, let $\mathfrak F_L(v)$ be the set of all (possibly infinite) non-empty $C$-compatible lower subsets $Z$ of $\mathbb F_{C}(v)$ such that each $z\in Z$ can be extended to an element of $Z$ not ending in $E^{-1}$ and not  ending in an edge $e$ such that $\{e\}\in C$. Set $\mathfrak F_L = \bigsqcup_{v\in E^0} \mathfrak F_L(v)$. 
		\item We order $\mathfrak F_L$ by inclusion, and let $\mathfrak U_L$ be the set of all maximal elements of $F_L$.
	\end{enumerate}

(cf. \cite[Proposition 5.1]{ABC25})
	\label{prop:characterizing-filt-ultra-L}
	With the above notation we have
	\begin{enumerate}
		\item The set $\mathcal F_L$ of filters of $\mathcal Y^L$ is order-isomorphic with 
		$\mathfrak{F}_L$.
		\item The set of ultrafilters of $\mathcal Y^L$ is isomorphic to $\mathfrak{U}_L$.
	\end{enumerate}

\label{def:exits}
	Let $Z\in  \mathfrak F_L$. An element in $\mathcal N ^{\mathrm{inf}}_L (Z)$ will be called an {\it infinite exit of} $Z$.
	An element of $\mathcal N ^{\mathrm{fin}}_L (Z)$ will be called a {\it finite exit of} $Z$. We say that $Z$ {\it does not have finite (respectively, infinite)} exits if $\mathcal N ^{\mathrm{fin}}_L (Z)= \emptyset$ (respectively, $\mathcal N ^{\mathrm{inf}}_L (Z)=\emptyset$). We say that $Z$ {\it does not have exits} if $\mathcal N ^{\mathrm{inf}}_L (Z) = \mathcal N ^{\mathrm{fin}}_L (Z)= \emptyset$.

\label{lem:opencompactbasisL}
	With the above notation, the family of sets $\mathcal Z_L (T\setminus F)$, where $T$ ranges on $\mathcal X _L$ and $F$ ranges on all finite subsets of $\mathcal N_L (T)$,
	is a basis of open compact subsets of $\mathfrak F_L$. Each open compact subset of $\mathfrak F_L$ is a finite disjoint union of sets $\mathcal Z_L (T\setminus F)$.

\label{thm:structure-isolated}
Let $x\in X^{\mathrm{iso}}$. Then we have
\begin{enumerate}
	\item $$1_x A_K(\mathcal{G}) 1_x \cong K \mathcal{G}^x_x,$$ 
	that is, the corner $*$-algebra $1_x A_K(\mathcal{G}) 1_x$ is $*$-isomorphic to the group $*$-algebra $K\mathcal{G}^x_x$ of the isotropy group $\mathcal{G}_x^x$. 
	\item $$A_K(\mathcal{G}) 1_x A_K(\mathcal{G}) \cong M_{\Lambda_x} (K\mathcal{G}_x^x),$$ 
	that is, the two-sided ideal
	$A_K(\mathcal{G}) 1_x A_K(\mathcal{G})$ generated by $1_x$ is $*$-isomorphic to the $*$-algebra of $\Lambda_x \times \Lambda_x$ matrices with coefficients in $K\mathcal{G}^x_x$.  
	\end{enumerate}

\cite[Definition 1.9]{Lolk:tame}
	\label{def:cycles}
	A non-trivial $C$-separated path $\alpha$ in a separated graph $(E,C)$ is called a {\it closed path} if $r(\alpha ) =s(\alpha)$, and it is called a {\it cycle} if $\alpha^2 := \alpha \alpha$ is also a $C$-separated path. In this case $\alpha^n$ is $C$-separated for each $n\in \mathbb Z$.\footnote{Here we interpret $\alpha^0$ as the trivial path at the vertex $s(\alpha)=r(\alpha)$, and for $n<0$ we set $\alpha^n := (\alpha^{-1})^{-n}$. In particular, if $\alpha \alpha$ is $C$-separated, then so are $\alpha^{-1}$ and all integer powers $\alpha^n$.}
 A {\it simple closed path} is a closed path $\alpha$ such that the only vertex repetition occurs at the end, that is, $\alpha_1 <_p \alpha_2 \le_p \alpha$ and $r(\alpha _1)= r(\alpha_2)$ implies that $\alpha_1 = s(\alpha)$ and  $\alpha_2 = \alpha$.

\cite{CCMMR25}
 	\label{def:LP}
 	Let $\mathcal{G}$ be an ample Hausdorff groupoid. We say that $\mathcal{G}$ satisfies condition (LP) if, for every $x\in \mathcal{G}^{(0)}$,
 	$$\text{soc} (K(\mathcal{G}^x_x))\ne 0 \iff \mathcal{G}_x^x = \{x\}.$$

\cite{CCMMR25}
\label{thm:mainCGMMR}
Let $\mathcal{G}$ be an ample Hausdorff groupoid satisfying condition {\rm(LP)}, with $X=\mathcal{G}^{(0)}$. The socle $\mathrm{soc}(A_K(\mathcal{G}))$ of $A_K(\mathcal{G})$ coincides with the ideal generated by all the characteristic functions $1_{x}$, where $x$ is an isolated point in $X= \mathcal{G}^{(0)}$ such that $\mathcal{G}_x^x= \{x\}$. Moreover 
$$\mathrm{soc} (A_K (\mathcal{G})) \cong \bigoplus_{[x]\in X^{\mathrm{iso}}_0/{\mathcal R}} M_{|[x]|} (K) ,$$
	where $X^{\mathrm{iso}}_0$ is the set of elements $x\in X^{\mathrm{iso}}$ such that $\mathcal{G}_x^x= \{x\}$, so that $X^{\mathrm{iso}}_0/{\mathcal R}$ is the set of orbits of $X^{\mathrm{iso}}_0$.

\label{lem:isotropy-when-all-groups-havemoreon-element}
	Let $(E,C)$ be a separated graph such that $|X| \ge 2$ for all $X\in C$, and suppose that $T$ is a Leavitt $(E,C)$-tree without exits. Suppose that $h\in \mathbb F_{C}$ is such that $T\cup h^\downarrow \in \mathcal X$ and $h\notin T$, and write $h= gg'$, where  $g\in T$, $g[g'] _1\notin T$. Then all the edges of $g'$ are inverse edges $e^{-1}\in E^{-1}$ with the property that $|C_{s(e)}| = 1$.
	Moreover, $T\in \Omega^{\mathrm{iso}}_0$ and thus $\Omega^{\mathrm{iso}} = \Omega^{\mathrm{iso}}_0$.

\label{prop:finite-orbits}
	Let $(E,C)$ be a separated graph such that $|X|\ge 2$ for all $X\in C$ and $|C_v|\ge 2$ for all $v\in E^0$ such that $C_v\neq \emptyset$. Then if $T\in \Omega^{\mathrm{iso}}$, the size of the orbit of $T$ is exactly $|T|$, the cardinality of $T$, and the elements of the orbit of $T$ are exactly $\{ \theta_{\alpha} (T): \alpha^{-1}\in T\}$. Moreover $r(\gamma)$ is a sink of $E$ for each $\gamma \in \mathrm{max} (T)$. Hence, we have
		$$ \mathrm{soc} (\mathcal L^\mathrm{ab} (E,C)) \cong \bigoplus_{[T]\in \Omega^{\mathrm{iso}}_0/{\mathcal R}} M_{|T|} (K).$$

\label{exam:socle-non-separated-graph}
	Let $E$ be a non-separated graph. Then $\mathrm{soc} (\mathcal L_K (E))$ is the ideal generated by the line points of $E$, which are the vertices $v$ of $E$ such that the tree of $v$ does not contain any bifurcation vertex or any cycle \cite[Theorem 2.6.14]{AAS}. 
	In the Leavitt model, a line point $v$ is represented by a single vertex $\{v\}$, which does not have exits and does not have isotropy. This differs from the representation in the standard model, where the line point is represented by the path consisting of the tree of $v$, which can be finite or infinite. The third picture, that is, the complete model, also gives a different representation. The points in the orbit of a line point $v$ are represented in the Leavitt model by the vertices in the tree of $v$, the line points connecting to $v$, and the finite paths $e_1\cdots e_r$ in $E$ such that $|s^{-1}(s(e_r))| \ge 2$ and $r(e_r)$ is a line point connecting to $v$. Note that these are all finite trees without exits, as predicted by Proposition \ref{prop:isoand-isoiso-forOmega}. \qed

\label{exam:Cuntz-free-separation}
Let $X$ be any non-empty set, and let $E_X$ be the graph with just one vertex $v$ and with $E_X^1 = X$. We consider the free separation $C=C_v= \{\{e\} : e\in X \}$ on $E_X$. This example was considered in \cite[Examples 3.3 and 4.9]{ABC25}. We have
$$\mathrm{soc} (\mathcal C_K^\mathrm{ab} (E_X,C)) = \begin{cases}
	M_{\infty} (K) & \text{ if } |X| = 1\\
\,\,\, \quad 	0 & \text{ if } |X|>1.
\end{cases}
$$
The case where $|X|= 1$ is well-known, and corresponds to a non-separated graph. In that case, $\mathcal C_K^{\mathrm{ab}}(E_X,C)$ is just the usual Toeplitz algebra. 

Assume that $|X| >1$. Let $T\in \mathcal X_0$. Then $T$ can be identified with a usual Munn tree over $X$, with the property that each maximal path does not end in $X^{-1}$. If $\gamma $ is a maximal path of $T$, then we can consider an element $\gamma \nu^{-1} y$, where $\nu$ is an arbitrary word in positive edges $x\in X$, in such a way that the word $\gamma \nu^{-1} y$ is reduced. Of course this is possible because $|X|>1$. Since $\nu$ has arbitrary length, we conclude that $\mathcal N (T)$ is infinite. Therefore $\mathcal X_{\mathrm cb}= \emptyset$ and thus $\mathrm{soc} ((\mathcal C_K^\mathrm{ab} (E_X,C)) ) =0$.

\label{prop:basis-for-I}
 		Let $A= K[\mathfrak{F_{im}} (X)]$, where $X$ is a non-empty set. Let $\mathcal I$ be the ideal of $A$ generated by the elements $1-xx^*$ and $1-x^*x$, for all $x\in X$. Then the set $\mathcal B (\mathcal I)$ consisting of all the elements $ \mathbf{e} (T\setminus F)\rtimes g$, where $(T\setminus F,g)$ is a blocked Munn tree such that all the maximal elements of $T$, except possibly $g$, are blocked by $F$, is a linear basis of $\mathcal I$. Hence 
 	$\mathcal B (\mathcal I)\cup \{1\rtimes g: g\in \mathbb F\}$ is a linear basis of $A$.

\label{prop:filtered-I}
 	Let $X$ be a finite non-empty set, and set $A= K[\mathfrak{F_{im}} (X)]$. Then the ideal $\mathcal I$ of $A$ has a filtered structure $\mathcal I =  \cup_{i=0}^\infty B_i$, where $B_i$ is the linear span of the set $\mathbf{e}(I\setminus F)\rtimes g$, where $I\setminus F$ has at most $i+1$ exits. 
 	In particular $B_0$ is a subalgebra of $A$ properly containing $\mathrm{soc} (A)$.
